#!/usr/bin/env python3
"""Re-embed src/summonner.json into SummonerJsonResource.ContentBase64."""

from __future__ import annotations

import base64
import sys
from pathlib import Path

JSON_TEMPLATE = """namespace Summoner.Skills;

/// <summary>
/// Auto-generated by embed_json.py — do not edit by hand.
/// </summary>
internal static class SummonerJsonResource
{{
    const string ContentBase64 = "{b64}";

    internal static bool TryOpen(out Stream stream)
    {{
        if (string.IsNullOrEmpty(ContentBase64))
        {{
            stream = null!;
            return false;
        }}

        stream = new MemoryStream(Convert.FromBase64String(ContentBase64));
        return true;
    }}

    internal static bool HasContent => !string.IsNullOrEmpty(ContentBase64);
}}
"""

VERSION_TEMPLATE = """namespace Summoner;

/// <summary>
/// Auto-generated by embed_json.py — do not edit by hand.
/// Source of truth: build.txt
/// </summary>
internal static class SummonerVersion
{{
    internal const string Value = "{ver}";
}}
"""


def embed(root: Path) -> None:
    json_path = root / "src" / "summonner.json"
    if not json_path.is_file():
        raise FileNotFoundError(f"summonner.json not found: {json_path}")

    b64 = base64.b64encode(json_path.read_bytes()).decode("ascii")
    out = root / "src" / "SummonerJsonResource.cs"
    out.write_text(JSON_TEMPLATE.format(b64=b64), encoding="utf-8", newline="\n")
    print(f"Embedded summonner.json into {out.relative_to(root)}")

    version_path = root / "build.txt"
    ver = "0.1.0"
    if version_path.is_file():
        ver = "".join(version_path.read_text(encoding="utf-8").split()) or ver
    version_out = root / "src" / "SummonerVersion.cs"
    version_out.write_text(
        VERSION_TEMPLATE.format(ver=ver), encoding="utf-8", newline="\n"
    )
    print(f"Embedded build.txt version {ver} into {version_out.relative_to(root)}")


def main() -> int:
    root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path(__file__).resolve().parent.parent
    embed(root)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
